const articles = $('Aggregate').first().json.articles;

return $('Users_a_servir').all().map(u => {
  const deja = new Set(u.json.deja_envoyees || []);
  return {
    json: {
      ...u.json,
      articles: articles.filter(a => !deja.has(a.url)),
    },
  };
});

